import React from 'react';
import {Html5Audio, interpolate, Sequence, staticFile} from 'remotion';

// Files are generated by audio-src/generate_audio.py into public/audio/.
export type SfxName =
  | 'whoosh-in'
  | 'whoosh-out'
  | 'paper-slide'
  | 'box-thump'
  | 'sparkle'
  | 'text-pop-1'
  | 'text-pop-2'
  | 'heel-tap'
  | 'magic-rise'
  | 'swell'
  | 'bell-chord';

/** One-shot sound effect starting at frame `at` of the current story. */
export const Sfx: React.FC<{name: SfxName; at: number; volume?: number}> = ({name, at, volume = 0.8}) => (
  <Sequence from={Math.round(at)} layout="none" name={`sfx ${name}`}>
    <Html5Audio src={staticFile(`audio/sfx-${name}.wav`)} volume={volume} />
  </Sequence>
);

export const MUSIC_VOLUME = 0.55;

/**
 * The series waltz is one 28-second piece, 4 bars (= 7 s = 210 frames) per story.
 * Each story plays its own slice so that stories posted back to back sound continuous.
 */
export const SeriesMusic: React.FC<{storyIndex: number; durationInFrames: number; fadeIn?: number; fadeOut?: number}> = ({
  storyIndex,
  durationInFrames,
  fadeIn = 4,
  fadeOut = 10,
}) => (
  <Html5Audio
    src={staticFile('audio/music-waltz.wav')}
    trimBefore={storyIndex * durationInFrames}
    trimAfter={(storyIndex + 1) * durationInFrames}
    volume={(f) =>
      MUSIC_VOLUME *
      interpolate(f, [0, fadeIn, durationInFrames - fadeOut, durationInFrames], [fadeIn ? 0 : 1, 1, 1, fadeOut ? 0 : 1], {
        extrapolateLeft: 'clamp',
        extrapolateRight: 'clamp',
      })
    }
  />
);

/** Whole piece, for the combined 28-second series video. */
export const FullSeriesMusic: React.FC = () => <Html5Audio src={staticFile('audio/music-waltz.wav')} volume={MUSIC_VOLUME} />;
